Okay, let's first consider an algorithm which actually works, i.e. obtain the subset of spheres with no overlap. To this end, we don't remove a sphere (before checking whether it overlaps with another one) but merely record that is has overlaps. struct sphere { double R,X,Y,Z; };

inline constexpr double square(double x) noexcept
{ return x*x; }

inline constexpr bool overlap(sphere const&a, sphere const&b) noexcept
{ return square(a.X-b.X)+square(a.Y-b.Y)+square(a.Z-b.Z) > square(a.R+b.R); }

std::vector<sphere> keep_non_overlapping(std::vector<sphere> const&S)
{
    std::vector<char> hasOverlap(Spheres.size(), char(0));
    vector<sphere> result;
    for(size_t i=0; i<S.size(); ++i) {
        for(size_t j=i+1; j<S.size(); ++j)
            if((!hasOverlap[i] || !hasOverlap[j]) && overlap(S[i],S[j])) {
                hasOverlap[i] = 1;
                hasOverlap[j] = 1;
            }
        if(!hasOverlap[i])
            result.push_back(S[i]);
    }
    return result;
} This algorithm loops every pair of spheres once. Since the test between spheres k and l is done when i equals the smaller of k and l and j the larger, the executions of the loop over i are still not mutually independent: there is still a race condition. This can be removed by looping over each pair of spheres twice: std::vector<sphere> keep_non_overlapping(std::vector<sphere> const&S)
{
    std::vector<char> hasOverlap(Spheres.size(), char(0));

    #pragma omp parallel for
    for(size_t i=0; i<S.size(); ++i) {
        bool overlapping = false;
        for(size_t j=0; !overlapping && j<S.size(); ++j)
            if(j!=i && overlap(S[i],S[j])
                overlapping = true;
        hasOverlap[i] = !overlapping;
    }

    vector<sphere> result;
    for(size_t i=0; i<S.size(); ++i)
        if(!hasOverlap[i])
            result.push_back(S[i]); 
    return result;
} Note also that, depending on the distribution of spheres, it can make the execution significantly faster if you first order the sphere is descending radius (largest spheres first) as in std::sort(S.begin(), S.end(), [](sphere const&a, sphere const&b) { return a.R > b.R; }); Note further that this naive O(N^2) algorithm is not optimal. There is likely a O(N ln(N)) algorithm which first arranges the spheres in some data structure (perhaps a spatial tree) in O(N ln(N)) time and then finds whether a sphere is overlapping in no more than O(ln N) time for each sphere.

