That part of GCC's documentation has not really been updated regularly, so it's probably a good idea to only read it as an approximation of what is actually happening.  If you're interested in that level of detail, I suggest you look at the debug files generated by -fdump-tree-all and similar options. With a recent version of GCC, your example generates a call to __builtin_GOMP_parallel , which maps to GOMP_parallel .  That one internally calls GOMP_parallel_end at the end, so that's what you're seeing, I suppose. void
GOMP_parallel (void (*fn) (void *), void *data, unsigned num_threads, unsigned int flags)
{ 
  num_threads = gomp_resolve_num_threads (num_threads, 0);
  gomp_team_start (fn, data, num_threads, flags, gomp_new_team (num_threads));
  fn (data);
  ialias_call (GOMP_parallel_end) ();
} Of course, patches to update the documentation will be gladly accepted.  :-)

here's one way. It's a variation on the idea of the schwartz counter to manage a global singleton (for example, std::cout itself) // globals.hpp
#include <istream>

struct globals_object
{
    globals_object()
    {
        // record number of source files which instanciate a globals_object
        ++init_count_;
    }

    ~globals_object()
    {
        // The last source file cleans up at program exit
        if(--init_count_ == 0)
        {
            if (pimpl_)
            {
                delete pimpl_;
            }
        }
    }

    // internal implementation   
    struct impl
    {
        void load(std::istream& is)
        {
            // do loading code here
        }

        int get_param_a() const {
            return a_;
        }

        int a_;
    };

    // (re)load global state    
    void load(std::istream&& is)
    {
        if (pimpl_) delete pimpl_;
        pimpl_ = new impl;
        pimpl_->load(is);
    }

    // public parameter accessor    
    int get_param_a() const {
        return get_impl().get_param_a();
    }

private:    
    static int init_count_;
    static impl* pimpl_;
    static impl& get_impl()
    {
        return *pimpl_;
    }
};
// one of these per translation unit
static globals_object globals;


// globals.cpp

// note - not initialised - will be zero-initialised
// before global constructors are called 
// you need one of these in a cpp file
int globals_object::init_count_;
globals_object::impl* globals_object::pimpl_;


// main file

// #include "globals.hpp"
#include <fstream>

int main()
{
    globals.load(std::ifstream("settings.yml"));

}


// any other file

// #include "globals.hpp"
#include <iostream>

void foo()
{
    std::cout << globals.get_param_a() << std::endl;
}

