The code as written hangs nearly every time I run it, never finishing, because one of the threads gets stuck at the barrier waiting for the others that already terminated. This happens because some thread checks elapsed at 9.99999 seconds and proceeds but another thread checks at 10 and exits. This is also why the finish count can be higher on some threads than on others because they go an extra round, also amid the run the increment values are sometimes not equal because some threads spend longer in the for loop printing out their current value than others who have already proceeded to wrap around to the next barrier to wait. In order to terminate the threads appropriately and to synchronize them perfectly a flag is needed which will be #pragma omp flush ed in order to break the threads at the same time, also another barrier after the increment comparison and print for loop is needed: #include <iostream>
#include <omp.h>
#include <vector>
#include <chrono>
#include <sstream>


int main()
{

    const auto start_time = std::chrono::high_resolution_clock::now();
    const int num_threads = 4;
    std::vector<int> arr(num_threads, 0);
    bool breakFlag = false;

#pragma omp parallel num_threads(num_threads) default(none) shared(start_time,arr,std::cout, breakFlag)
    {

        int thread_num = omp_get_thread_num();
        while (true) {
            // Check elapsed time
            auto now = std::chrono::high_resolution_clock::now();
            auto elapsed = std::chrono::duration_cast<std::chrono::seconds>(now - start_time).count();
            if (elapsed >= 10) breakFlag = true;


            arr[thread_num]++;
            std::stringstream ss;
            ss << "Thread " << thread_num << " done grinding.\n";
            std::cout << ss.str();

#pragma omp barrier // Wait for other threads
#pragma omp flush(breakFlag)
            if(breakFlag) break;

            // Read other threads' values
            for (int i = 0; i < num_threads; ++i) {
                if (i != thread_num && arr[i] != arr[thread_num]) {
                    std::stringstream _ss;
                    _ss << "Thread " << thread_num << ": My value is " << arr[thread_num]
                              << ", but thread " << i << "'s value is " << arr[i] << ".\n";
                    std::cout << _ss.str();
                }
            }
#pragma omp barrier // Wait for other threads

        }
    }

    std::cout << "Final array values:\n";
    for (int i = 0; i < num_threads; ++i) {
        std::cout << "Index " << i << ": " << arr[i] << "\n";
    }

    return 0;
}

I am answering with Ray since you allowed for "OpenMP threads or similar". Ray makes parallelizing python really easy -- you could do what you want with the following (assuming you have four cores on your machine): import ray

def _encode_sample(self, idxes):
    split_idxes = np.array_split(idxes, 4)
    for subrange in split_idxes:
        futures.append(_encode_sample_helper.remote(self.storage, subrange))

    obses_t, actions, rewards, obses_tp1, dones = [], [], [], [], []
    outputs = ray.get(futures)

    for a, b, c, d, e in outputs:
        obses_t.extend(a)
        actions.extend(b)
        rewards.extend(c)
        obses_tp1.extend(d)
        dones.extend(e)

    return np.array(obses_t), np.array(actions), np.array(rewards), np.array(obses_tp1), np.array(dones)


@ray.remote(num_cpus=1)
def _encode_sample_helper(storage, subrange):
    obses_t, actions, rewards, obses_tp1, dones = [], [], [], [], []
    for i in subrange:
        data = storage[i]
        obs_t, action, reward, obs_tp1, done = data
        obses_t.append(np.array(obs_t, copy=False))
        actions.append(np.array(action, copy=False))
        rewards.append(reward)
        obses_tp1.append(np.array(obs_tp1, copy=False))
        dones.append(done)
    return np.array(obses_t), np.array(actions), np.array(rewards), np.array(obses_tp1), np.array(dones)

