Running it without any changes its around 0.00775 sec To really see the benefits of the parallelism you need to increase your input size. Otherwise, the computation being performed in parallel will not be enough to overcome the additional overhead introduced with the parallelism (e.g., thread creation and synchronization) Let us start by declaring the variables closer to the scope where they will used. This will avoid having to explicitly add OpenMP pragmas to make those variables private ( i.e., private(it, k, i) ) double dphimax;
for (it=1;it<=itmax;it++){    
    dphimax=0.0;
    for (k=1;k<kmax;k++){
       for (i=1;i<imax;i++){
          dphi=(phi[i+1][k]+phi[i-1][k]-2.*phi[i][k])*dy2i
              +(phi[i][k+1]+phi[i][k-1]-2.*phi[i][k])*dx2i;
          dphi=dphi*dt;
          dphimax=max(dphimax,dphi);
          phin[i][k]=phi[i][k]+dphi;
      }
   }
    for (k=1;k<kmax;k++)
      for (i=1;i<imax;i++)
          phi[i][k]=phin[i][k];
    if(dphimax<eps) break;
} For the parallel region we can try to add the entire chunk of code: double dphimax;
#pragma omp parallel
for (it=1;it<=itmax;it++){    
    ....
} Now let us look of which loops iterations can be divided among threads. The outermost loop would not work because there are dependencies between its iterations. The next candidate, is the loop: for (k=1;k<kmax;k++){
   for (i=1;i<imax;i++){
      dphi=(phi[i+1][k]+phi[i-1][k]-2.*phi[i][k])*dy2i
          +(phi[i][k+1]+phi[i][k-1]-2.*phi[i][k])*dx2i;
      dphi=dphi*dt;
      dphimax=max(dphimax,dphi);
      phin[i][k]=phi[i][k]+dphi;
  } } To parallelize this one we need to fix the race-condition on the updates of the variable dphimax , for that we can use the reduction clause of OpenMP: #pragma omp for reduction(max: dphimax)
  for (int k=1; k<kmax; k++){
     for (int i=1; i<imax ;i++){
       double dphi=(phi[i+1][k]+phi[i-1][k]-2.*phi[i][k])*dy2i +
                   (phi[i][k+1]+phi[i][k-1]-2.*phi[i][k])*dx2i;
       dphi = dphi * dt;
       dphimax = max(dphimax, dphi);
       phin[i][k] = phi[i][k] + dphi;
     }
 } We can also parallelize the last loop: #pragma omp for
for (k=1;k<kmax;k++)
  for (i=1;i<imax;i++)
      phi[i][k]=phin[i][k]; You can also play around with vectorizing it instead: #pragma omp simd
for (k=1;k<kmax;k++)
  for (i=1;i<imax;i++)
      phi[i][k]=phin[i][k]; Everything put together: double dphimax;
#pragma omp parallel
for (it=1;it<=itmax;it++){    
    dphimax=0.0;
    #pragma omp for reduction(max: dphimax)
    for (k=1;k<kmax;k++){
       for (i=1;i<imax;i++){
          dphi=(phi[i+1][k]+phi[i-1][k]-2.*phi[i][k])*dy2i
              +(phi[i][k+1]+phi[i][k-1]-2.*phi[i][k])*dx2i;
          dphi=dphi*dt;
          dphimax=max(dphimax,dphi);
          phin[i][k]=phi[i][k]+dphi;
      }
   }
    #pragma omp for
    for (k=1;k<kmax;k++)
      for (i=1;i<imax;i++)
          phi[i][k]=phin[i][k];
    if(dphimax<eps) break;
}

