I'm testing a hybrid approach by paralleling the friendly-numbers (CAPBenchmark) program with MPI and OpenMP. My cluster has 8 machines and each machine has a 4 core processor. The code: /*
 * Copyright(C) 2014 Pedro H. Penna < [email protected] >
 * 
 * friendly-numbers.c - Friendly numbers kernel.
 */

#include <global.h>
#include <mpi.h>
#include <omp.h>
#include <stdio.h>
#include <stdlib.h>
#include <util.h>
#include "fn.h"

/*
 * Computes the Greatest Common Divisor of two numbers.
 */
static int gcd(int a, int b)
{
  int c;

  /* Compute greatest common divisor. */
  while (a != 0)
  {
     c = a;
     a = b%a;
     b = c;
  }

  return (b);
}

/*
 * Some of divisors.
 */
static int sumdiv(int n)
{
    int sum;    /* Sum of divisors. */
    int factor; /* Working factor.  */

    sum = 1 + n;

    /* Compute sum of divisors. */
    for (factor = 2; factor < n; factor++)
    {
        /* Divisor found. */
        if ((n%factor) == 0)
            sum += factor;
    }

    return (sum);
}

/*
 * Computes friendly numbers.
 */
int friendly_numbers(int start, int end) 
{
    int n;        /* Divisor.                    */
    int *num;     /* Numerator.                  */
    int *den;     /* Denominator.                */
    int *totalnum;
    int *totalden;
    int rcv_friends;
    int range;    /* Range of numbers.           */
    int i, j;     /* Loop indexes.               */
    int nfriends; /* Number of friendly numbers. */
    int slice;

    range = end - start + 1;
    slice = range / nthreads;
    if (rank == 0) {

        num = smalloc(sizeof(int)*range);
        den = smalloc(sizeof(int)*range);
        totalnum = smalloc(sizeof(int)*range);
        totalden = smalloc(sizeof(int)*range);

    } else {

        num = smalloc(sizeof(int) * slice);
        den = smalloc(sizeof(int) * slice);
        totalnum = smalloc(sizeof(int)*range);
        totalden = smalloc(sizeof(int)*range);
    }

    j = 0;
    omp_set_dynamic(0);    
    omp_set_num_threads(4);
    #pragma omp parallel for private(i, j, n) default(shared) 
    for (i = start + rank * slice; i < start + (rank + 1) * slice; i++) { 
            j = i - (start + rank * slice);
            num[j] = sumdiv(i);
            den[j] = i;

            n = gcd(num[j], den[j]);
            num[j] /= n;
            den[j] /= n;
    }
    if (rank != 0) {
        MPI_Send(num, slice, MPI_INT, 0, 0, MPI_COMM_WORLD);
        MPI_Send(den, slice, MPI_INT, 0, 1, MPI_COMM_WORLD);
    } else {
        for (i = 1; i < nthreads; i++)  {
            MPI_Recv(num + (i * (slice)), slice, MPI_INT, i, 0, MPI_COMM_WORLD, 0);
            MPI_Recv(den + (i * (slice)), slice, MPI_INT, i, 1, MPI_COMM_WORLD, 0);
        }
    }

    if (rank == 0) {
        for (i = 1; i < nthreads; i++) {
            MPI_Send(num, range, MPI_INT, i, 2, MPI_COMM_WORLD);
            MPI_Send(den, range, MPI_INT, i, 3, MPI_COMM_WORLD);
        }
    } else {
        MPI_Recv(totalnum, range, MPI_INT, 0, 2, MPI_COMM_WORLD,0);
        MPI_Recv(totalden, range, MPI_INT, 0, 3, MPI_COMM_WORLD,0);
    }

    /* Check friendly numbers. */
    nfriends = 0;
    if (rank == 0) {
        omp_set_dynamic(0);
        omp_set_num_threads(4);
        #pragma omp parallel for private(i, j) default(shared) reduction(+:nfriends)
        for (i = rank; i < range; i += nthreads) {
            for (j = 0; j < i; j++) {
                /* Friends. */
                if ((num[i] == num[j]) && (den[i] == den[j])) 
                    nfriends++;
            }
        }
    } else {
        omp_set_dynamic(0);
        omp_set_num_threads(4);
        #pragma omp parallel for private(i, j) default(shared) reduction(+:nfriends)
        for (i = rank; i < range; i += nthreads) {
            for (j = 0; j < i; j++) {
                /* Friends. */
                if ((totalnum[i] == totalnum[j]) && (totalden[i] == totalden[j])) 
                    nfriends++;
            }
        }

    }
    if (rank == 0) {
        for (i = 1; i < nthreads; i++) {
            MPI_Recv(&rcv_friends, 1, MPI_INT, i, 4, MPI_COMM_WORLD, 0);
            nfriends += rcv_friends;
        }
    } else {
        MPI_Send(&nfriends, 1, MPI_INT, 0, 4, MPI_COMM_WORLD);
    }

    free(num);
    free(den);

    return (nfriends);
} During the executions I observed the following behavior: When I run mpirun with 4 and 8 hosts, each of the hosts uses 4 threads for processing, as expected. However when running using only 2 hosts only 1 thread is used on each machine.
What could cause this behavior? Is there any alternative to "force" the use of the 4 threads in the case of the 2 hosts?

I have written a code for a special type of 3D CFD Simulation, the Lattice-Boltzmann Method (quite similar to a code supplied with the Book "The Lattice Boltzmann Method" by Timm Krüger et alii).
Multithreading the program with OpenMP I have experienced issues that I can't quite understand: The results prove to be strongly dependent on the overall domain size. The basic principle is that each cell of a 3D domain gets assigned certain values for 19 distribution functions (0-18) in discrete directions. They are laid down in two linear arrays allocated in the heap (one population is layed out in a separte array): The 18 populations of a certain cell are contiguous in memory, the values of consecutive x-values lay next to each other and so on (so sort of row-major: populations->x->y->z).
Those distribution functions redistribute according to certain values within the cell and then get streamed to the neighbouring cells. For this reason I have two populations f1 and f2. The algorithm takes the values from f1, redistributes them and copies them into f2. Then the pointers are swapped and the algorithm starts again.
The code is working perfectly fine on a single core but when I try to parallelise it on multiple cores I get a performance that depends on the overall size of the domain: For very small domains (10^3 cells) the algorithm is comparably slow with 15 million cells per second, for quite small domains (30^3 cells) the algorithm is about quite fast with over 60 million cells per second and for anything larger than that the performance drops again to about 30 million cells per second. Executing the code on a single core only leads to the same performance of about 15 million cells per second. These results of course vary between different processors but qualitatively the same issue remains! The core of the code boils down to this parallelised loop that is executed over and over again and the pointers to f1 and f2 are swapped: #pragma omp parallel for default(none) shared(f0,f1,f2) schedule(static)
    for(unsigned int z = 0; z < NZ; ++z)
    {
        for(unsigned int y = 0; y < NY; ++y)
        {
            for(unsigned int x = 0; x < NX; ++x)
            {
                /// temporary populations
                double ft0  = f0[D3Q19_ScalarIndex(x,y,z)];
                double ft1  = f1[D3Q19_FieldIndex(x,y,z,1)];
                double ft2  = f1[D3Q19_FieldIndex(x,y,z,2)];
                double ft3  = f1[D3Q19_FieldIndex(x,y,z,3)];
                double ft4  = f1[D3Q19_FieldIndex(x,y,z,4)];
                double ft5  = f1[D3Q19_FieldIndex(x,y,z,5)];
                double ft6  = f1[D3Q19_FieldIndex(x,y,z,6)];
                double ft7  = f1[D3Q19_FieldIndex(x,y,z,7)];
                double ft8  = f1[D3Q19_FieldIndex(x,y,z,8)];
                double ft9  = f1[D3Q19_FieldIndex(x,y,z,9)];
                double ft10 = f1[D3Q19_FieldIndex(x,y,z,10)];
                double ft11 = f1[D3Q19_FieldIndex(x,y,z,11)];
                double ft12 = f1[D3Q19_FieldIndex(x,y,z,12)];
                double ft13 = f1[D3Q19_FieldIndex(x,y,z,13)];
                double ft14 = f1[D3Q19_FieldIndex(x,y,z,14)];
                double ft15 = f1[D3Q19_FieldIndex(x,y,z,15)];
                double ft16 = f1[D3Q19_FieldIndex(x,y,z,16)];
                double ft17 = f1[D3Q19_FieldIndex(x,y,z,17)];
                double ft18 = f1[D3Q19_FieldIndex(x,y,z,18)];

                /// microscopic to macroscopic
                double r    = ft0 + ft1 + ft2 + ft3 + ft4 + ft5 + ft6 + ft7 + ft8 + ft9 + ft10 + ft11 + ft12 + ft13 + ft14 + ft15 + ft16 + ft17 + ft18;
                double rinv = 1.0/r;
                double u    = rinv*(ft1 - ft2 + ft7 + ft8  + ft9   + ft10 - ft11 - ft12 - ft13 - ft14);
                double v    = rinv*(ft3 - ft4 + ft7 - ft8  + ft11  - ft12 + ft15 + ft16 - ft17 - ft18);
                double w    = rinv*(ft5 - ft6 + ft9 - ft10 + ft13 -  ft14 + ft15 - ft16 + ft17 - ft18);

                /// collision & streaming
                double trw0 = omega*r*w0;                   //temporary variables
                double trwc = omega*r*wc;
                double trwd = omega*r*wd;
                double uu   = 1.0 - 1.5*(u*u+v*v+w*w);

                double bu = 3.0*u;
                double bv = 3.0*v;
                double bw = 3.0*w;

                unsigned int xp = (x + 1) % NX;             //calculate x,y,z coordinates of neighbouring cells
                unsigned int yp = (y + 1) % NY;
                unsigned int zp = (z + 1) % NZ;
                unsigned int xm = (NX + x - 1) % NX;
                unsigned int ym = (NY + y - 1) % NY;
                unsigned int zm = (NZ + z - 1) % NZ;

                f0[D3Q19_ScalarIndex(x,y,z)]      = bomega*ft0  + trw0*(uu);                        //redistribute distribution functions and stream to neighbouring cells
                double cu = bu;
                f2[D3Q19_FieldIndex(xp,y, z,  1)] = bomega*ft1  + trwc*(uu + cu*(1.0 + 0.5*cu));
                cu = -bu;
                f2[D3Q19_FieldIndex(xm,y, z,  2)] = bomega*ft2  + trwc*(uu + cu*(1.0 + 0.5*cu));
                cu = bv;
                f2[D3Q19_FieldIndex(x, yp,z,  3)] = bomega*ft3  + trwc*(uu + cu*(1.0 + 0.5*cu));
                cu = -bv;
                f2[D3Q19_FieldIndex(x, ym,z,  4)] = bomega*ft4  + trwc*(uu + cu*(1.0 + 0.5*cu));
                cu = bw;
                f2[D3Q19_FieldIndex(x, y, zp, 5)] = bomega*ft5  + trwc*(uu + cu*(1.0 + 0.5*cu));
                cu = -bw;
                f2[D3Q19_FieldIndex(x, y, zm, 6)] = bomega*ft6  + trwc*(uu + cu*(1.0 + 0.5*cu));
                cu = bu+bv;
